        for (int a = 0; a < NAT; a++) tma2d(sm + s*STG + 16384 + a*8192, mapB, n0 + a*64, kb*64, full + s);
      }
      __syncwarp();
    }
  } else if (warp == 1) {
    const u32 idesc = (1u<<4) | (1u<<16) | ((u32)(NT>>3)<<17) | ((u32)(128>>4)<<24);
    unsigned long long t0 = clock64();
    for (int kb = 0; kb < nk; kb++) {
      const int s = kb % S; const u32 ph = (kb / S) & 1;
      mb_wait(full + s, ph); tfa();
      if (elect1()) {
        const u32 a0 = sa(sm + s*STG), b0 = a0 + 16384;
        #pragma unroll
        for (int k = 0; k < 4; k++) mma_f16(tb, sdesc(a0 + k*32, 16, 1024), sdesc(b0 + k*2048, 8192, 1024), idesc, (kb|k) != 0);
        mma_commit(empty + s);
        if (kb == nk - 1) mma_commit(done);
      }
      __syncwarp();
    }
    mb_wait(done, 0);
    if (lane == 0 && clk) clk[blockIdx.y * gridDim.x + blockIdx.x] = clock64() - t0;
  }
  tfb(); __syncthreads();
  if (warp == 2) asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, 256;"::"r"(tb));
}
