def run(M, N, K, NT, SMAX=8):
    A = (torch.randn(M, K, device='cuda')/K**0.5).half(); B = torch.randn(K, N, device='cuda').half()
    mA = tmap(A, 64, 128); mB = tmap(B, 64, 64)
    clk = torch.zeros(4096, dtype=torch.int64, device='cuda')
