    print(f"M{M} N{N} K{K} NT{NT} S<={SMAX} ctas {n} warm {tw:.2f} us cold {tc:.2f} us | warm mma clk med {cl.median().item():.0f} max {cl.max().item():.0f} per-kb {cl.median().item()/(K//64):.0f} (ideal {2*NT})")
